def collect(center, r, plate):
    tot=0
    for f in get_entities({Prototype.StoneFurnace}, position=center, radius=r):
        n = inspect_inventory(f).get(plate.value[0], 0)
        if abs(player_location.x-f.position.x)>7 or abs(player_location.y-f.position.y)>7:
            move_to(Position(x=f.position.x, y=f.position.y-2))
        if n>0:
            tot += extract_item(plate, f, n)
        if f.fuel.get('coal',0) < 5:
            insert_item(Prototype.Coal, f, 5)
    return tot
