D = {"U":Direction.UP,"D":Direction.DOWN,"L":Direction.LEFT,"R":Direction.RIGHT}
def path(pts, last):
    tiles=[]
    for i in range(len(pts)-1):
        x0,y0=pts[i]; x1,y1=pts[i+1]
        dx = (x1>x0)-(x1<x0); dy=(y1>y0)-(y1<y0)
        d = "R" if dx>0 else "L" if dx<0 else "D" if dy>0 else "U"
        x,y=x0,y0
        while (x,y)!=(x1,y1):
            tiles.append((x,y,d)); x+=dx; y+=dy
    tiles.append((pts[-1][0],pts[-1][1],last))
    return tiles
def lay(tiles, proto=Prototype.TransportBelt):
    fails=[]; last=None
